contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Read before-state
        uint before = c.depositsCount();

        // Try the receive() entry point (non-owner caller since msg.sender is this test contract)
        bool reverted;
        try c.receive{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state
        uint afterCount = c.depositsCount();

        // Rule: non-owner call to receive() reverts and depositsCount is unchanged
        assert(reverted && afterCount == before);
    }

    receive() external payable {}
}

